module dog_show(\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] n,\n    input [7:0] T,\n    input [7:0] t_i_0,\n    input [7:0] t_i_1,\n    input [7:0] t_i_2,\n    input [7:0] t_i_3,\n    input [7:0] t_i_4,\n    input [7:0] t_i_5,\n    input [7:0] t_i_6,\n    input [7:0] t_i_7,\n    output reg [3:0] result,\n    output reg done\n);\n\n    localparam [3:0] IDLE        = 4'd0;\n    localparam [3:0] PREPROCESS  = 4'd1;\n    localparam [3:0] SORT_EVENTS = 4'd2;\n    localparam [3:0] SWEEP       = 4'd3;\n    localparam [3:0] DONE_STATE  = 4'd4;\n\n    reg [3:0] state;\n    reg [2:0] i;\n    reg [4:0] event_count;\n    reg [7:0] events_time [0:15];\n    reg       events_is_end [0:15];\n    reg [7:0] counter;\n    reg [7:0] max_count;\n    reg [3:0] j;\n    reg [3:0] k;\n    reg [7:0] t_i [0:7];\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 4'd0;\n            event_count <= 5'd0;\n            counter <= 8'd0;\n            max_count <= 8'd0;\n            i <= 3'd0;\n            j <= 4'd0;\n            k <= 4'd0;\n            for (integer m = 0; m < 16; m = m + 1) begin\n                events_time[m] <= 8'd0;\n                events_is_end[m] <= 1'b0;\n            end\n            for (integer m = 0; m < 8; m = m + 1) begin\n                t_i[m] <= 8'd0;\n            end\n        end else begin\n            t_i[0] <= t_i_0;\n            t_i[1] <= t_i_1;\n            t_i[2] <= t_i_2;\n            t_i[3] <= t_i_3;\n            t_i[4] <= t_i_4;\n            t_i[5] <= t_i_5;\n            t_i[6] <= t_i_6;\n            t_i[7] <= t_i_7;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    result <= 4'd0;\n                    if (start) begin\n                        state <= PREPROCESS;\n                        i <= 3'd0;\n                        event_count <= 5'd0;\n                    end\n                end\n\n                PREPROCESS: begin\n                    if (i < n) begin\n                        if (T >= (i + 3'd2)) begin\n                            reg [7:0] m_val;\n                            if (t_i[i] > (i + 3'd1))\n                                m_val = t_i[i] - i - 3'd1;\n                            else\n                                m_val = 8'd0;\n                            \n                            reg [7:0] M_val = T - i - 3'd2;\n                            \n                            if (m_val <= M_val) begin\n                                events_time[event_count] <= m_val;\n                                events_is_end[event_count] <= 1'b0;\n                                events_time[event_count + 1] <= M_val + 1;\n                                events_is_end[event_count + 1] <= 1'b1;\n                                event_count <= event_count + 5'd2;\n                            end\n                        end\n                        i <= i + 3'd1;\n                    end else begin\n                        if (event_count != 5'd0) begin\n                            state <= SORT_EVENTS;\n                            j <= 4'd0;\n                        end else begin\n                            state <= DONE_STATE;\n                            result <= 4'd0;\n                        end\n                    end\n                end\n\n                SORT_EVENTS: begin\n                    if (j < event_count - 1) begin\n                        if (k < event_count - j - 1) begin\n                            if (\n                                (events_time[k] > events_time[k+1]) ||\n                                (events_time[k] == events_time[k+1] && events_is_end[k] > events_is_end[k+1])\n                            ) begin\n                                reg [7:0] temp_time;\n                                reg temp_is_end;\n                                temp_time = events_time[k];\n                                temp_is_end = events_is_end[k];\n                                events_time[k] <= events_time[k+1];\n                                events_is_end[k] <= events_is_end[k+1];\n                                events_time[k+1] <= temp_time;\n                                events_is_end[k+1] <= temp_is_end;\n                            end\n                            k <= k + 4'd1;\n                        end else begin\n                            k <= 4'd0;\n                            j <= j + 4'd1;\n                        end\n                    end else begin\n                        state <= SWEEP;\n                        i <= 4'd0;\n                        counter <= 8'd0;\n                        max_count <= 8'd0;\n                    end\n                end\n\n                SWEEP: begin\n                    if (i < event_count) begin\n                        if (!events_is_end[i]) begin\n                            counter <= counter + 8'd1;\n                            if (counter + 8'd1 > max_count)\n                                max_count <= counter + 8'd1;\n                        end else begin\n                            counter <= counter - 8'd1;\n                        end\n                        i <= i + 4'd1;\n                    end else begin\n                        result <= max_count[3:0];\n                        state <= DONE_STATE;\n                    end\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule